// row for a digital LED type, nullptr for other types (PWM, network, on/off, HUB75) and unused IDs
constexpr const LedTypeDef* ledType(uint8_t id) {
  for (const LedTypeDef& t : LED_TYPE_TABLE) if (t.id == id) return &t;
  return nullptr;
}

// true if id is a digital LED type with all of flags
constexpr bool ledTypeHas(uint8_t id, uint8_t flags) {
  const LedTypeDef* t = ledType(id);
  return t && (t->flags & flags) == flags;
}

// bit timing of a digital LED type (WS2812 timing for others, which do not use it)
inline WLEDpixelBus::LedTiming ledTypeTiming(uint8_t id) {
  const LedTypeDef* t = ledType(id);
  if (!t) t = ledType(TYPE_WS2812_RGB);
  return WLEDpixelBus::LedTiming(t->t0h, t->t0l, t->t1h, t->t1l, t->trst);
}
